void CGeometry::SetCustomBoundary(CConfig* config) {
  unsigned short iMarker;
  unsigned long iVertex;
  string Marker_Tag;

  /*--- Initialize quantities for customized boundary conditions.
   * Custom values are initialized with the default values specified in the config (avoiding non physical values) ---*/
  CustomBoundaryTemperature = new su2double*[nMarker];
  CustomBoundaryHeatFlux = new su2double*[nMarker];

  for (iMarker = 0; iMarker < nMarker; iMarker++) {
    Marker_Tag = config->GetMarker_All_TagBound(iMarker);
    CustomBoundaryHeatFlux[iMarker] = nullptr;
    CustomBoundaryTemperature[iMarker] = nullptr;
    if (config->GetMarker_All_PyCustom(iMarker)) {
      switch (config->GetMarker_All_KindBC(iMarker)) {
        case HEAT_FLUX:
          CustomBoundaryHeatFlux[iMarker] = new su2double[nVertex[iMarker]];
          for (iVertex = 0; iVertex < nVertex[iMarker]; iVertex++) {
            CustomBoundaryHeatFlux[iMarker][iVertex] = config->GetWall_HeatFlux(Marker_Tag);
          }
          break;
        case ISOTHERMAL:
          CustomBoundaryTemperature[iMarker] = new su2double[nVertex[iMarker]];
          for (iVertex = 0; iVertex < nVertex[iMarker]; iVertex++) {
            CustomBoundaryTemperature[iMarker][iVertex] = config->GetIsothermal_Temperature(Marker_Tag);
          }
          break;
        case INLET_FLOW:
          // This case is handled in the solver class.
          break;
        default:
          cout << "WARNING: Marker " << Marker_Tag << " is not customizable. Using default behavior." << endl;
          break;
      }
    }
  }

if (KindBC == BC_TYPE::HEAT_FLUX) {
  HeatFlux[iMarker][iVertex] =
      py_custom ? -geometry->GetCustomBoundaryHeatFlux(iMarker, iVertex) : Wall_HeatFlux_Value;
} else if (KindBC == BC_TYPE::ISOTHERMAL) {
  const su2double Twall_local =
      py_custom ? geometry->GetCustomBoundaryTemperature(iMarker, iVertex) / RefTemperature : Twall;
  const auto iPointNormal = geometry->vertex[iMarker][iVertex]->GetNormal_Neighbor();
  const su2double* Coord_Normal = geometry->nodes->GetCoord(iPointNormal);
  const su2double dist_ij = GeometryToolbox::NormalDistance(nDim, UnitNormal, Coord, Coord_Normal);
  const su2double There = nodes->GetTemperature(iPointNormal);
  HeatFlux[iMarker][iVertex] = thermal_conductivity * (There - Twall_local) / dist_ij * RefHeatFlux;
} else {
  su2double dTdn = GeometryToolbox::DotProduct(nDim, Grad_Temp, UnitNormal);
  if (FlowRegime == ENUM_REGIME::INCOMPRESSIBLE && !energy) dTdn = 0.0;
  HeatFlux[iMarker][iVertex] = thermal_conductivity * dTdn * RefHeatFlux;
}
